mapper.select:

WHERE t.user_id = #{userId}
AND t.wallet_id = #{walletId}
AND t.type = #{type}
AND t.direction = #{direction}
AND t.category_id = #{categoryId}
AND t.occurred_at >= #{from}
AND t.occurred_at < #{to}

    AND (t.note LIKE CONCAT('%', #{keyword}, '%')
         OR t.counterparty_name LIKE CONCAT('%', #{keyword}, '%'))

ORDER BY t.occurred_at DESC, t.id DESC

SELECT
    COALESCE(SUM(CASE WHEN type IN ('income', 'transfer_in') AND status = 'success' THEN amount ELSE 0 END), 0) AS income,
    COALESCE(SUM(CASE WHEN type = 'transfer_out' AND status = 'success' THEN amount + COALESCE(fee_amount, 0)
                      WHEN type = 'expense' AND status = 'success' THEN amount
                      ELSE 0 END), 0) AS spent
FROM transactions
WHERE user_id = #{userId}
  AND occurred_at >= #{start}
  AND occurred_at < #{end}
AND wallet_id = #{walletId}
